const d = $input.first().json;

// Pega primeiro nome para mensagem mais humanizada
const nome = (d.nome_cliente || 'querida').split(' ')[0];
const srv = d.servico_nome || 'o serviço';
const extras = d.informacoes_extras || '';

// Busca mensagem customizada em informacoes_extras do tenant
// Formato esperado: mensagem_posvenda: Oi {nome}! Texto da mensagem
let msg_pv;
const m = extras.match(/mensagem_posvenda:\s*(.+?)(?:\n|$)/i);
if (m) {
  msg_pv = m[1]
    .replace(/{nome}/g, nome)
    .replace(/{servico}/g, srv);
} else {
  msg_pv = 'Oi ' + nome + '! Tudo bem? Passando pra saber como foi o atendimento hoje 😊 Ficou satisfeita com ' + srv + '? Qualquer coisa estou por aqui!';
}

// Calcula data de retorno se serviço tiver intervalo configurado
let calcular_retorno = false;
let data_retorno_prevista = '';
const intervalo = parseInt(d.intervalo_retorno_dias || 0);

if (intervalo > 0 && d.ativo_followup === true) {
  const base = d.data_fim ? new Date(d.data_fim) : new Date();
  const retorno = new Date(base.getTime() + (intervalo * 86400000));
  data_retorno_prevista = retorno.toISOString().split('T')[0]; // YYYY-MM-DD
  calcular_retorno = true;
}

// Delay aleatório anti-spam (1 a 3 segundos)
const delaySeconds = parseFloat((1 + Math.random() * 2).toFixed(1));

return [{
  json: {
    ...d,
    msg_pv,
    calcular_retorno: String(calcular_retorno),
    data_retorno_prevista,
    delaySeconds
  }
}];

const d = $input.first().json;

// Pega primeiro nome
const nome = (d.nome_cliente || 'querida').split(' ')[0];
const srv = d.servico_nome || 'o serviço';
const intervalo = parseInt(d.intervalo_retorno_dias || 30);

// Usa mensagem customizada do serviço, ou template padrão
let mensagem;
if (d.mensagem_retorno && d.mensagem_retorno.trim() !== '') {
  mensagem = d.mensagem_retorno
    .replace(/{nome}/g, nome)
    .replace(/{servico}/g, srv)
    .replace(/{dias}/g, String(intervalo));
} else {
  mensagem = 'Oi ' + nome + '! Já faz ' + intervalo + ' dias desde seu ' + srv + ' 💅 Que tal renovar? Posso verificar um horário disponível pra você essa semana!';
}

// Delay aleatório anti-spam (1 a 3 segundos)
const delaySeconds = parseFloat((1 + Math.random() * 2).toFixed(1));

return [{
  json: {
    ...d,
    mensagem,
    delaySeconds
  }
}];
